pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_sqs::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_sqs::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "add_permission" => Box::pin(call_add_permission(&client, input, &output)),
            "cancel_message_move_task" => {
                Box::pin(call_cancel_message_move_task(&client, input, &output))
            }
            "change_message_visibility" => {
                Box::pin(call_change_message_visibility(&client, input, &output))
            }
            "change_message_visibility_batch" => Box::pin(call_change_message_visibility_batch(
                &client, input, &output,
            )),
            "create_queue" => Box::pin(call_create_queue(&client, input, &output)),
            "delete_message" => Box::pin(call_delete_message(&client, input, &output)),
            "delete_message_batch" => Box::pin(call_delete_message_batch(&client, input, &output)),
            "delete_queue" => Box::pin(call_delete_queue(&client, input, &output)),
            "get_queue_attributes" => Box::pin(call_get_queue_attributes(&client, input, &output)),
            "get_queue_url" => Box::pin(call_get_queue_url(&client, input, &output)),
            "list_dead_letter_source_queues" => {
                Box::pin(call_list_dead_letter_source_queues(&client, input, &output))
            }
            "list_message_move_tasks" => {
                Box::pin(call_list_message_move_tasks(&client, input, &output))
            }
            "list_queue_tags" => Box::pin(call_list_queue_tags(&client, input, &output)),
            "list_queues" => Box::pin(call_list_queues(&client, input, &output)),
            "purge_queue" => Box::pin(call_purge_queue(&client, input, &output)),
            "receive_message" => Box::pin(call_receive_message(&client, input, &output)),
            "remove_permission" => Box::pin(call_remove_permission(&client, input, &output)),
            "send_message" => Box::pin(call_send_message(&client, input, &output)),
            "send_message_batch" => Box::pin(call_send_message_batch(&client, input, &output)),
            "set_queue_attributes" => Box::pin(call_set_queue_attributes(&client, input, &output)),
            "start_message_move_task" => {
                Box::pin(call_start_message_move_task(&client, input, &output))
            }
            "tag_queue" => Box::pin(call_tag_queue(&client, input, &output)),
            "untag_queue" => Box::pin(call_untag_queue(&client, input, &output)),
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("sqs", operation))
    })
}
